package updater

import (
	"context"
	"errors"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/nodelock"
)

// D-158 is a contention policy, not a maximum holder lifetime. It applies to
// run, seed, apply and standalone flush, which can overlap a serving agent.
const updateLockWaitBudget = 10 * time.Second

const lockRetryInterval = 20 * time.Millisecond
const promptLockAttempts = 5

// acquireCommandLock leaves the common lock APIs and their consumers unchanged.
// Stale metadata switches to the existing five-attempt window, counted from
// the first stale answer, even if live contention preceded it. Later attempts
// may acquire a released lock; otherwise the final diagnostic is preserved.
func (e *Engine) acquireCommandLock(ctx context.Context, command string) (lk *nodelock.Lock, err error) {
	started := time.Now()
	waited := false
	defer func() {
		if waited {
			e.log().Info("update lock wait", "command", command,
				"waited_ms", time.Since(started).Milliseconds(), "acquired", lk != nil,
				"budget_ms", updateLockWaitBudget.Milliseconds())
		}
	}()
	staleAttempts := 0
	for {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		lk, err = nodelock.AcquireWithBootID(ctx, e.Layout.Lock, 1, 0, e.Node.BootID.String())
		if err == nil {
			return lk, nil
		}
		waited = true
		if !errors.Is(err, nodelock.ErrBusy) {
			return nil, err
		}
		if staleAttempts > 0 {
			staleAttempts++
		} else if lockBusyDetail(err) != "lock" {
			staleAttempts = 1
		}
		if staleAttempts == promptLockAttempts {
			return nil, err
		}
		delay := lockRetryInterval
		if staleAttempts == 0 {
			remaining := updateLockWaitBudget - time.Since(started)
			if remaining <= 0 {
				return nil, err
			}
			delay = min(delay, remaining)
		}
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, ctx.Err()
		case <-timer.C:
		}
	}
}

// Command fvpn-agent is the exit-node agent (§5, §16.3).
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"github.com/TED-H-com/Freedom-VPN/node/agent"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	switch os.Args[1] {
	case "enroll":
		os.Exit(enroll(os.Args[2:]))
	case "run":
		os.Exit(run(os.Args[2:], true))
	case "step":
		os.Exit(run(os.Args[2:], false))
	case "version":
		fmt.Println("fvpn-agent dev")
	case "usage":
		os.Exit(usageCommand(os.Args[2:]))
	default:
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: fvpn-agent enroll -config path -token-file path|-")
	fmt.Fprintln(os.Stderr, "       fvpn-agent run|step -config path")
	fmt.Fprintln(os.Stderr, "       fvpn-agent usage snapshot -config path [-json]")
	fmt.Fprintln(os.Stderr, "       fvpn-agent version")
}

func enroll(args []string) int {
	fs := flag.NewFlagSet("enroll", flag.ContinueOnError)
	config := fs.String("config", "", "path to agent.json")
	tokenFile := fs.String("token-file", "", "enrollment token file, or - for stdin")
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 || *config == "" || *tokenFile == "" {
		usage()
		return 2
	}
	// The token is read from the file or stdin only. The environment is ignored (§6.1).
	token, err := agent.ReadToken(*tokenFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: token file")
		return 1
	}
	eng, err := open(*config)
	if err != nil {
		if agent.ExitStatus(err) == agent.ExitUsage {
			fmt.Fprintln(os.Stderr, "fvpn-agent: configuration error: host_reserve_bps is required and must be greater than zero")
			return agent.ExitUsage
		}
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	defer eng.Close()
	if err := eng.Enroll(context.Background(), token); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: enrollment failed")
		return 1
	}
	if err := agent.NeutralizeToken(*tokenFile); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: token file")
		return 1
	}
	return 0
}

type runEngine interface {
	Run(context.Context) error
	Boot(context.Context) error
	Step(context.Context) error
	Close() error
}

func run(args []string, loop bool) int {
	return runWithOpen(args, loop, func(path string) (runEngine, error) { return open(path) })
}

func runWithOpen(args []string, loop bool, open func(string) (runEngine, error)) int {
	// Cover startup too, and retain signal handling until Close has completed.
	// Supervisors may send another TERM while the local checkpoint is running.
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	fs := flag.NewFlagSet("run", flag.ContinueOnError)
	config := fs.String("config", "", "path to agent.json")
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 || *config == "" {
		usage()
		return 2
	}
	eng, err := open(*config)
	if err != nil {
		if agent.ExitStatus(err) == agent.ExitUsage {
			fmt.Fprintln(os.Stderr, "fvpn-agent: configuration error: host_reserve_bps is required and must be greater than zero")
			return agent.ExitUsage
		}
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	defer eng.Close()
	if loop {
		if err := eng.Run(ctx); err != nil && (errors.Is(err, agent.ErrBoot) || ctx.Err() == nil || !errors.Is(err, ctx.Err())) {
			fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
			return 1
		}
		return 0
	}
	if err := eng.Boot(ctx); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	if err := eng.Step(ctx); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	return 0
}

func open(path string) (*agent.Engine, error) {
	cfg, err := agent.LoadConfig(path)
	if err != nil {
		return nil, err
	}
	log := slog.New(agent.RedactHandler{Next: slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo})})
	return agent.Start(agent.Options{Config: cfg, Log: log})
}

package agent

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/json"
