package secops

import (
	"fmt"
	"strconv"
	"time"
)

func decimal18(n int64) string { return strconv.FormatInt(n, 10) }

func faultDeadline18(lease nodeLease16, accepted bool, heartbeat map[string]string, now int64, grantEnd time.Time) (int64, error) {
	duration := lease.Expires.Sub(lease.Issued)
	hb := heartbeat["policy_expires_mono_ns"]
	fail := func(reason string) (int64, error) {
		return 0, fmt.Errorf("lease %s generation=%s issued=%s cap=%ds lifetime=%s D=%d heartbeat_D=%s accepted=%t read_mono=%d: %s", lease.ID, lease.Generation, lease.Issued.Format(time.RFC3339Nano), lease.Max, duration, lease.Deadline, hb, accepted, now, reason)
	}
	if !accepted || lease.ID == "" || lease.Sent <= 0 {
		return fail("not a locally accepted lease")
	}
	if lease.Max != 60 || duration <= 0 || duration > 60*time.Second {
		return fail("not signed under the 60s cap")
	}
	if lease.Deadline != lease.Sent+int64(duration) || hb != decimal18(lease.Deadline) || heartbeat["serving"] != "1" {
		return fail("accepted lease does not match serving heartbeat deadline")
	}
	if now < lease.Sent || lease.Deadline <= now {
		return fail("accepted deadline is not in the future at the read")
	}
	if grantEnd.IsZero() {
		return fail("missing grant end")
	}
	d := lease.Deadline
	if grantEnd.Before(lease.Expires) {
		d = lease.Sent + int64(grantEnd.Sub(lease.Issued))
	}
	if d <= now {
		return fail("earlier grant deadline is not in the future")
	}
	return d, nil
}

#!/usr/bin/env python3
"""D-160 admission journal and timed-section protocol, owned by the harness."""
import datetime
import json
import os
from pathlib import Path
import subprocess
import sys
import time


def stamp():
    return dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00', 'Z'),
                mono_ns=str(time.monotonic_ns()))


def append(event):
    path = os.environ.get('FVPN_SECOPS_TIMING_JOURNAL')
    if not path:
        raise RuntimeError('timing journal is required')
    with open(path, 'a', encoding='utf-8') as out:
        out.write(json.dumps(event, separators=(',', ':'))+'\n')


def active():
    path = os.environ.get('FVPN_SECOPS_TIMING_ACTIVE')
    return Path(path).read_text() if path and Path(path).exists() else ''


def check(command):
    if active():
        raise RuntimeError('admission check forbidden inside timed section')
    started = stamp()
    admission_env = dict(os.environ, PATH=os.environ.get('FVPN_SECOPS_ADMISSION_PATH', os.environ['PATH']))
    result = subprocess.run(['bash', os.environ['FVPN_HOLD_SH']], capture_output=True, text=True, env=admission_env)
    free = result.returncode == 0 and result.stdout.strip() == 'free'
    # No private reasons, paths or foreign argv in public evidence.
    event = dict(kind='admission', command=command, answer='free' if free else 'held',
                 started=started, **stamp())
    append(event)
    return free


def admit(command, sleep=time.sleep):
    for attempt in range(121):
        if check(command):
            return
        if attempt == 120:
            raise RuntimeError('120-minute admission limit reached')
        sleep(60)


def begin(name):
    if active():
        raise RuntimeError('nested timed section')
    admit('timed-section:'+name)
    event = dict(kind='section_start', section=name, **stamp())
    # No child command can run between marker installation and the receipt.
    Path(os.environ['FVPN_SECOPS_TIMING_ACTIVE']).write_text(name)
    append(event)
    return event


def end(name):
    if active() != name:
        raise RuntimeError('timed section mismatch')
    event = dict(kind='section_end', section=name, **stamp())
    append(event)
    Path(os.environ['FVPN_SECOPS_TIMING_ACTIVE']).unlink()
    return event


def before_command(command):
    section = active()
    if section:
        # This is an execution receipt, NOT an admission check. D-133 monitor
        # observes overlaps without delaying the subject or querying admission.
        append(dict(kind='timed_command', section=section, command=command, **stamp()))
    else:
        admit(command)


def validate(events):
    errors, sections, opened = [], [], None
    previous = None
    for event in events:
        kind = event['kind']
        if kind == 'section_start':
            if not previous or previous['kind'] != 'admission' or previous.get('answer') != 'free' or previous.get('command') != 'timed-section:'+event['section']:
                errors.append('missing free boundary admission: '+event['section'])
            if opened:
                errors.append('nested section: '+event['section'])
            opened = event
        elif kind == 'section_end':
            if not opened or opened['section'] != event['section']:
                errors.append('unmatched section end: '+event['section'])
            else:
                sections.append(dict(section=opened['section'], start=opened, end=event))
            opened = None
        previous = event
    if opened:
        errors.append('unclosed section: '+opened['section'])
    for event in events:
        n = int(event['mono_ns'])
        if event['kind'] == 'admission':
            first = int(event.get('started', event)['mono_ns'])
            for section in sections:
                if first <= int(section['end']['mono_ns']) and n >= int(section['start']['mono_ns']):
                    errors.append(event['answer']+' admission inside '+section['section'])
        if event['kind'] == 'timed_command' and not any(
                s['section'] == event['section'] and int(s['start']['mono_ns']) <= n <= int(s['end']['mono_ns'])
                for s in sections):
            errors.append('command outside declared section: '+event['section'])
    return dict(passed=not errors, errors=errors, sections=sections,
                admission_checks=[e for e in events if e['kind']=='admission'],
                timed_command_count=sum(e['kind']=='timed_command' for e in events))


def main():
    action, name = sys.argv[1:3]
    if action == 'command':
        before_command(name)
    else:
        result = begin(name) if action == 'begin' else end(name)
        print(json.dumps(result))


if __name__ == '__main__':
    main()

"""Hard admission stop; count suite roots, not nested make/wrapper processes."""
import os
import subprocess
import sys
import time
import json
import shlex
from pathlib import Path


def suite_roots(matches, parents, own_pid):
    ancestors = set()
    while own_pid and own_pid not in ancestors:
        ancestors.add(own_pid)
        own_pid = parents.get(own_pid, 0)
    candidates = set(matches) - ancestors
    roots = []
    for pid in candidates:
        parent = parents.get(pid, 0)
        seen = set()
        nested = False
        while parent and parent not in seen:
            seen.add(parent)
            if parent in candidates:
                nested = True
                break
            parent = parents.get(parent, 0)
        if not nested:
            roots.append(pid)
    return sorted(roots)


def process_args(command):
    # ps/pgrep render argv without shell escaping. A literal unmatched quote in
    # an argument is not a malformed process and must not crash admission or
    # disappear from the inventory. Conservative tokenization keeps it counted.
    try:
        return shlex.split(command)
    except ValueError:
        return command.split()


def inventory():
    found = subprocess.run(['pgrep', '-af', 'gates.sh|mk/at-|node-test-netlab|mk/netlab|test.*tags.*netlab'], text=True, capture_output=True)
    if found.returncode not in (0, 1):
        raise RuntimeError('suite inventory unavailable')
    parents = {}
    for line in subprocess.check_output(['ps', '-eo', 'pid=,ppid='], text=True).splitlines():
        pid, parent = map(int, line.split())
        parents[pid] = parent
    matches = {}
    for line in found.stdout.splitlines():
        pid, command = line.split(maxsplit=1)
        args = process_args(command)
        # Ignore orchestration shells containing quoted command text.
        if any(a in ('-c', '-lc', '-ec') for a in args[:3]):
            continue
        if args and Path(args[0]).name != 'pgrep':
            matches[int(pid)] = line
    roots = suite_roots(matches, parents, os.getpid())
    return matches, roots


def priority(matches, roots):
    return any(any(term in matches[p] for term in ('mk/at-isolation.mk', 'node-test-netlab', 'mk/netlab', '-tags netlab')) for p in roots)


def check():
    matches, roots = inventory()
    print('Admission: other active suites =', len(roots), flush=True)
    for pid in roots:
        # Keep the raw process command in private run logs only.
        print(matches[pid], flush=True)
    if len(roots) >= 2 or priority(matches, roots):
        print('HARD STOP: isolation active or two other suites; no test launched', flush=True)
        return 75
    return 0


if __name__ == '__main__':
    sys.exit(check())


def wait_ready():
    started = time.monotonic()
    isolation_wait = False
    polls = []
    while True:
        matches, roots = inventory()
        isolation = priority(matches, roots) or any('gates.sh' in matches[p] for p in roots)
        isolation_wait = isolation_wait or isolation
        polls.append(dict(elapsed_seconds=round(time.monotonic()-started, 3), other_suites=len(roots), isolation_active=isolation))
        if not isolation and len(roots) < 2:
            break
        if time.monotonic()-started >= 90*60:
            raise RuntimeError('90-minute suite admission wait exhausted; no run started')
        print('Waiting for isolation / suite admission:', polls[-1], flush=True)
        time.sleep(60)
    receipt=dict(wait_seconds=round(time.monotonic()-started, 3), waited_for_isolation=isolation_wait, polls=polls)
    Path('.agent/tmp/f18-admission-wait.json').write_text(json.dumps(receipt, indent=2)+'\n')
    return receipt

import unittest
import sys
sys.dont_write_bytecode = True
from admission import suite_roots, process_args


class AdmissionTest(unittest.TestCase):
    def test_unmatched_quote_is_retained_as_a_candidate(self):
        args = process_args('python3 gates.sh --label "unfinished')
        self.assertEqual(args[:2], ['python3', 'gates.sh'])
        self.assertEqual(args[-1], '"unfinished')

    def test_orchestration_shell_is_still_recognizable(self):
        args = process_args("bash -c echo 'mk/at-members.mk")
        self.assertEqual(args[:2], ['bash', '-c'])
        self.assertEqual(process_args('make -f mk/at-members.mk at-members'),
                         ['make', '-f', 'mk/at-members.mk', 'at-members'])

    def test_nested_make_and_current_runner_do_not_double_count(self):
        parents = {10: 1, 11: 10, 20: 1, 21: 20, 30: 1, 31: 30}
        self.assertEqual(suite_roots({10, 11, 20, 21, 30}, parents, 31), [10, 20])

    def test_two_standalone_targets_stop_admission(self):
        self.assertEqual(len(suite_roots({10, 20}, {10: 1, 20: 1}, 30)), 2)


if __name__ == '__main__':
    unittest.main()

#!/usr/bin/env python3
"""D-160 command admission. Receipts never share a tool's stdout/stderr.

Use `admission.py run <command...>` to wrap a foreground command tree. A timed
section is admitted by the Go harness before it exports its section name.
Children record that name and execute without another check or admission wait.
No reservation is taken. No arguments or private admission text are published.
"""
import datetime
import json
import os
import pathlib
import shutil
import subprocess
import sys
import tempfile
import time


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def record(row):
    path = os.environ.get('FVPN_E2E_ADMISSION_LOG')
    if not path:
        raise RuntimeError('FVPN_E2E_ADMISSION_LOG is required for admission')
    data = (json.dumps(row, separators=(',', ':')) + '\n').encode()
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    try:
        os.write(fd, data)
    finally:
        os.close(fd)


def admit(label, check=None, sleep=time.sleep, monotonic=time.monotonic):
    if check is None:
        check = lambda: subprocess.run(['bash', os.environ['FVPN_HOLD_SH']],
                                       capture_output=True, text=True)
    begin = monotonic()
    while True:
        at = now()
        result = check()
        free = result.returncode == 0 and result.stdout.strip() == 'free'
        record({'event': 'admission', 'at': at, 'answered_at': now(),
                'label': label, 'answer': 'free' if free else 'held',
                'exit_code': result.returncode})
        if free:
            return
        if monotonic() - begin >= 7200:
            raise SystemExit(125)
        sleep(min(60, 7200 - (monotonic() - begin)))


def tool(name, paths):
    section = os.environ.get('FVPN_E2E_TIMED_SECTION')
    if section:
        record({'event': 'command_in_section', 'at': now(), 'command': name,
                'section': section, 'admission_checked': False})
    else:
        admit(name)
    # argv[0] stays PATH-relative: recursive GNU Make must use this wrapper.
    os.execve(paths[name], [name] + sys.argv[1:], os.environ)


def run(command):
    if not os.environ.get('FVPN_HOLD_SH') or os.environ.get('FVPN_E2E_ADMISSION_WRAPPED'):
        return subprocess.call(command)
    with tempfile.TemporaryDirectory(prefix='e2e-admission-', dir=os.environ['TMPDIR']) as directory:
        bindir = pathlib.Path(directory)
        paths = {name: shutil.which(name) for name in ('go', 'make', 'docker', 'npm')}
        if not all(paths.values()):
            raise RuntimeError('missing command for admission wrappers')
        (bindir / 'paths.json').write_text(json.dumps(paths))
        for name in paths:
            (bindir / name).symlink_to(pathlib.Path(__file__).resolve())
        env = os.environ.copy()
        env['PATH'] = str(bindir) + os.pathsep + env['PATH']
        env['FVPN_E2E_ADMISSION_WRAPPED'] = '1'
        return subprocess.call(command, env=env)


if __name__ == '__main__':
    name = pathlib.Path(sys.argv[0]).name
    if name in ('go', 'make', 'docker', 'npm'):
        paths = json.loads((pathlib.Path(sys.argv[0]).parent / 'paths.json').read_text())
        tool(name, paths)
    elif sys.argv[1] == 'check':
        if os.environ.get('FVPN_E2E_TIMED_SECTION'):
            raise RuntimeError('admission check forbidden inside a timed section')
        admit(sys.argv[2])
    elif sys.argv[1] == 'run':
        raise SystemExit(run(sys.argv[2:]))
    else:
        raise SystemExit('expected check or run')

package e2e

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"time"
)

// TimedSections admits before reading any scenario clock or deadline. Its
// conservative intervals include the entire scenario, including its cleanup.
// Child tool wrappers cannot wait for admission during these intervals.
// The acceptance runner is sequential; nested helpers inherit the section.
type TimedSections struct{ Root, Log, active string }

func (s *TimedSections) event(event, name string) error {
	if err := os.MkdirAll(filepath.Dir(s.Log), 0o755); err != nil {
		return err
	}
	f, err := os.OpenFile(s.Log, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		return err
	}
	defer f.Close()
	return json.NewEncoder(f).Encode(map[string]any{"event": event, "section": name, "at": time.Now().UTC().Format(time.RFC3339Nano)})
}

func (s *TimedSections) Admit(ctx context.Context, name string) error {
	if s.active != "" {
		return fmt.Errorf("admission inside section %s", s.active)
	}
	if err := os.MkdirAll(filepath.Dir(s.Log), 0o755); err != nil {
		return err
	}
	if os.Getenv("FVPN_HOLD_SH") == "" {
		return s.event("admission_not_configured", name)
	}
	cmd := exec.CommandContext(ctx, "python3", "-B", filepath.Join(s.Root, "deploy/devstack/admission.py"), "check", name)
	cmd.Env = append(os.Environ(), "FVPN_E2E_ADMISSION_LOG="+s.Log)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("section admission: %w: %s", err, Redact(string(output)))
	}
	return nil
}

func (s *TimedSections) Begin(ctx context.Context, name string) (func() error, error) {
	if s.active != "" {
		return nil, fmt.Errorf("nested section %s inside %s", name, s.active)
	}
	if err := s.Admit(ctx, name); err != nil {
		return nil, err
	}
	if err := os.Setenv("FVPN_E2E_TIMED_SECTION", name); err != nil {
		return nil, err
	}
	if err := s.event("section_start", name); err != nil {
		_ = os.Unsetenv("FVPN_E2E_TIMED_SECTION")
		return nil, err
	}
	s.active = name
	return func() error {
		if s.active != name {
			return fmt.Errorf("section %s already ended", name)
		}
		err := s.event("section_end", name)
		_ = os.Unsetenv("FVPN_E2E_TIMED_SECTION")
		s.active = ""
		return err
	}, nil
}

