// The follow-up campaign's archived failures are part of the public artifact.
func TestCommittedFixtureEvidence_ValidAndHygieneClean(t *testing.T) {
	root := "../../docs/e2e/runs"
	if _, err := os.Stat(root); os.IsNotExist(err) {
		t.Skip("no committed follow-up fixture records")
	}
	records := 0
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if strings.HasPrefix(filepath.Base(filepath.Dir(path)), "2026-") && d.Name() != "followup16" && d.Name() != "followup17" && d.Name() != "followup18" && d.Name() != "followup19" && d.Name() != "followup20" && d.Name() != "followup21" && d.Name() != "followup22" && d.Name() != "followup23" && d.Name() != "followup24" && d.Name() != "followup25" && d.Name() != "followup26" && d.Name() != "followup27" && d.Name() != "followup29" && d.Name() != "followup30" && d.Name() != "followup31" && d.Name() != "followup32" && d.Name() != "followup33" && d.Name() != "followup34" && d.Name() != "followup35" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.Contains(path, "/followup") {
			return nil
		}
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		// Follow-up 27 keeps large captures losslessly compressed. Scan the
		// original bytes under their logical extension, never compressed noise.
		if strings.HasSuffix(path, ".gz") {
			reader, err := gzip.NewReader(bytes.NewReader(raw))
			if err != nil {
				return err
			}
			raw, err = io.ReadAll(io.LimitReader(reader, (256<<20)+1))
			closeErr := reader.Close()
			if err != nil {
				return err
			}
			if closeErr != nil {
				return closeErr
			}
			if len(raw) > 256<<20 {
				t.Fatalf("oversized compressed capture: %s", path)
			}
			path = strings.TrimSuffix(path, ".gz")
		}
		if filepath.Ext(path) == ".jsonl" && (strings.Contains(path, "/followup22/") || strings.Contains(path, "/followup23/") || strings.Contains(path, "/followup24/") || strings.Contains(path, "/followup25/") || strings.Contains(path, "/followup26/") || strings.Contains(path, "/followup27/")) {
			if len(raw) == 0 && emptyCaptureCertified(path) {
				return nil
			}
			for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
				var header map[string]json.RawMessage
				if json.Unmarshal([]byte(line), &header) != nil || header["packet"] == nil || header["timestamp"] == nil || header["header_error"] != nil {
					t.Errorf("invalid header evidence: %s", path)
				}
				for _, key := range []string{"payload", "data", "publicKey", "privateKey", "hostname", "mac"} {
					if header[key] != nil {
						t.Errorf("non-header evidence: %s", path)
					}
				}
			}
		}
		if filepath.Ext(path) == ".json" && filepath.Base(path) == "analysis.json" && (strings.Contains(path, "/followup22/") || strings.Contains(path, "/followup23/") || strings.Contains(path, "/followup24/") || strings.Contains(path, "/followup25/") || strings.Contains(path, "/followup26/") || strings.Contains(path, "/followup27/")) {
			var a struct {
				Schema string            `json:"schema"`
				Rows   []json.RawMessage `json:"rows"`
			}
			if json.Unmarshal(raw, &a) != nil || a.Schema != "native-capture-analysis-v1" || len(a.Rows) < 7 {
				t.Errorf("invalid native analysis: %s", path)
			}
		} else if filepath.Ext(path) == ".json" {
			var rec Record
			if json.Unmarshal(raw, &rec) != nil || rec.ID == "" || rec.RunID == "" || len(rec.SourceCommit) != 40 {
				t.Errorf("invalid fixture record: %s", path)
			}
			switch rec.Status {
			case StatusPass, StatusBlocked, StatusFail:
			default:
				t.Errorf("invalid claim: %s", path)
			}
			records++
		}
		for _, bad := range []string{"/ho" + "me/", "BEGIN " + "EC PRIVATE KEY", "BEGIN " + "RSA PRIVATE KEY", "BEGIN " + "OPENSSH PRIVATE KEY", "sk_" + "live_", "gh" + "p_", "gh" + "o_", "user_code=", "\"password\":", "\"setup_key\":"} {
			if strings.Contains(string(raw), bad) {
				t.Errorf("unsafe committed evidence: %s", path)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if records == 0 {
		t.Fatal("no fixture records scanned")
	}
}

// A stopped zero-packet capture is valid evidence, including an attempt that
// failed before its first request. Require its original capture receipt;
// arbitrary empty JSONL files must not silently pass hygiene.
func emptyCaptureCertified(path string) bool {
	role := strings.Split(filepath.Base(path), ".")[0]
	id := filepath.Base(filepath.Dir(path))
	root := filepath.Dir(filepath.Dir(filepath.Dir(path)))
	raw, err := os.ReadFile(filepath.Join(root, id+".json"))
	if err != nil {
		return false
	}
	var record Record
	if json.Unmarshal(raw, &record) != nil {
		return false
	}
	for _, o := range record.Observations {
		if o.Name != "capture" {
			continue
		}
		var capture struct {
			Points map[string]struct {
				Captured int  `json:"captured"`
				Drops    int  `json:"kernel_drops"`
				OK       bool `json:"statistics_ok"`
				Stopped  bool `json:"process_stopped"`
				Receipt  struct {
					Bytes string `json:"bytes"`
					SHA   string `json:"sha256"`
				} `json:"private_pcap_receipt"`
			} `json:"points"`
		}
		if json.Unmarshal([]byte(o.Detail), &capture) != nil {
			return false
		}
		point, ok := capture.Points[role]
		return ok && point.Captured == 0 && point.Drops == 0 && point.OK && point.Stopped && point.Receipt.Bytes == "24" && len(point.Receipt.SHA) == 64
	}
	return false
}

package agent

import (
	"encoding/json"
	"errors"
	"log/slog"
	"os"
	"syscall"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/enforce"
	"github.com/TED-H-com/Freedom-VPN/node/internal/timeanchor"
	"github.com/TED-H-com/Freedom-VPN/pkg/decstr"
	"github.com/google/uuid"
)

// Measurement is an opt-in TEST ONLY local record, never an HTTP observation.
// Timing is the detached enforcement snapshot, including failed/partial calls.
// Anchor brackets wall sampling with CLOCK_MONOTONIC in this boot/time namespace.
// Consumers must reject missing/unordered samples and sequence gaps. Nothing is
// written or called back inside an enforcement operation or guard bracket.
type Measurement struct {
	RunID     uuid.UUID               `json:"run_id"`
	BootID    uuid.UUID               `json:"boot_id"`
	Sequence  decstr.U64              `json:"sequence"`
	Source    string                  `json:"source"`
	Anchor    MeasurementAnchor       `json:"anchor"`
	Timing    *enforce.TimingEvidence `json:"timing,omitempty"`
	TC        string                  `json:"tc_sha256,omitempty"`
	Lease     *MeasurementLease       `json:"lease,omitempty"`
	Renewal   *MeasurementRenewal     `json:"renewal,omitempty"`
	Baseline  *MeasurementBaseline    `json:"baseline,omitempty"`
	Heartbeat *MeasurementHeartbeat   `json:"heartbeat,omitempty"`
	Host      *MeasurementHost        `json:"host,omitempty"`
}

// Baseline brackets the actual writer call, including failed calls. Cause is
// fixed vocabulary, never an executor error, selector, or signed document.
type MeasurementBaseline struct {
	Cause     string        `json:"cause"`
	Start     time.Duration `json:"start_ns,string"`
	End       time.Duration `json:"end_ns,string"`
	Succeeded bool          `json:"succeeded"`
}

type MeasurementHeartbeat struct {
	Mono          time.Duration `json:"mono_ns,string"`
	PolicyExpires time.Duration `json:"policy_expires_mono_ns,string"`
	Generation    decstr.U64    `json:"generation"`
	BaselineOK    bool          `json:"baseline_ok"`
	Serving       bool          `json:"serving"`
	Reason        string        `json:"reason"`
	Written       bool          `json:"written"`
}

func (e *Engine) baselineCall(cause string, call func() error) error {
	start, _ := timeanchor.Mono()
	log := e.log
	if log == nil {
		log = slog.New(slog.DiscardHandler)
	}
	log.Info("baseline write", "writer", "agent", "cause", cause, "phase", "begin", "mono_ns", int64(start), "generation", e.appliedGen)
	err := call()
	end, _ := timeanchor.Mono()
	log.Info("baseline write", "writer", "agent", "cause", cause, "phase", "end", "mono_ns", int64(end), "succeeded", err == nil)
	e.writeMeasurement(Measurement{Source: "baseline", Baseline: &MeasurementBaseline{cause, start, end, err == nil}})
	return err
}

func (e *Engine) baselineReason() string {
	switch {
	case e.identityFrozen:
		return "identity_frozen"
	case e.revoked:
		return "identity_revoked"
	case e.latchBlocked:
		return "updater_barrier"
	case e.recoverBlocked:
		return "updater_recovery"
	case e.applyError != nil:
		return "verification_" + string(e.applyError.Code)
	case e.conntrackBlocked:
		return "conntrack_blocked"
	case e.shutUsage:
		return "shutdown"
	case e.policyExpires > 0 && e.clock.Mono() >= e.policyExpires:
		return "policy_deadline"
	case len(e.decision.Reasons) > 0:
		return string(e.decision.Reasons[0])
	default:
		return "non_serving"
	}
}

type MeasurementAnchor struct {
	MonoBefore time.Duration `json:"mono_before_ns,string"`
	Wall       time.Time     `json:"wall"`
	MonoAfter  time.Duration `json:"mono_after_ns,string"`
}

type MeasurementLease struct {
	ID           uuid.UUID     `json:"lease_id"`
	Generation   decstr.U64    `json:"generation"`
	IssuedAt     time.Time     `json:"issued_at"`
	ExpiresAt    time.Time     `json:"expires_at"`
	RequestMono  time.Duration `json:"request_mono_ns,string"`
	NodeDeadline time.Duration `json:"node_deadline_ns,string"`
	Members      int           `json:"members"`
}

type MeasurementRenewal struct {
	RequestID uuid.UUID     `json:"request_id"`
	Start     time.Duration `json:"start_ns,string"`
	End       time.Duration `json:"end_ns,string"`
	Wall      time.Time     `json:"request_wall"`
	// NewLease distinguishes a newly accepted lease from replay, rejection
	// and failed requests. Lease is always the currently retained lease.
	NewLease bool `json:"new_lease"`
}

func (e *Engine) measurementEnabled() bool {
	return e.cfg.TestMode && e.cfg.TestTimingPath != ""
}

func (e *Engine) measureTiming(ev enforce.ServingEvidence, source string, host ...*MeasurementHost) {
	if !e.measurementEnabled() {
		return
	}
	timing := ev.TimingEvidence()
	if timing == nil { // a fake Plane may not run enforcement at all
		return
	}
	m := Measurement{Source: source, Timing: timing}
	if len(host) > 0 {
		m.Host = host[0]
	}
	if tc := ev.TCReadbackEvidence(); tc != nil {
		m.TC = tc.Sha256
	}
	e.writeMeasurement(m)
}

func (e *Engine) measureLease(id uuid.UUID, start time.Duration, wall time.Time) {
	e.writeMeasurement(Measurement{Source: "renewal", Renewal: &MeasurementRenewal{
		RequestID: id, Start: start, End: e.clock.Mono(), Wall: wall.UTC(),
		NewLease: e.leaseFresh && e.leaseMono == start,
	}})
}

func (e *Engine) writeMeasurement(m Measurement) {
	if !e.measurementEnabled() {
		return
	}
	if e.measurementRun == uuid.Nil {
		var err error
		e.measurementRun, err = uuid.NewRandom()
		if err != nil {
			e.log.Warn("measurement unavailable")
			return
		}
	}
	e.measurementSequence++
	m.RunID, m.BootID, m.Sequence = e.measurementRun, e.bootID, decstr.U64(e.measurementSequence)
	m.Anchor.MonoBefore, _ = timeanchor.Mono()
	m.Anchor.Wall = time.Now().UTC()
	m.Anchor.MonoAfter, _ = timeanchor.Mono()
	if l := e.lease; l != nil {
		d, _ := timeanchor.MemberDeadline(e.leaseMono, l.ExpiresAt.Sub(l.IssuedAt))
		m.Lease = &MeasurementLease{l.LeaseId, l.ConfigGeneration, l.IssuedAt.UTC(), l.ExpiresAt.UTC(), e.leaseMono, d, len(l.Members)}
	}
	if err := appendMeasurement(e.cfg.TestTimingPath, m); err != nil {
		// No path or underlying error text. A gap invalidates the diagnostic;
		// measurement I/O cannot rewrite a serving decision or D-106 evidence.
		e.log.Warn("measurement unavailable")
	}
}

func appendMeasurement(path string, m Measurement) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_APPEND|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0o600)
	if err != nil {
		return err
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		return err
	}
	if !st.Mode().IsRegular() {
		return errors.New("measurement requires regular file")
	}
	return json.NewEncoder(f).Encode(m)
}

// Package nodelock is the node-wide exclusive update lock of §13.5: the agent,
// the manual installer and the updater take the same flock before they change
// the version pointer, the state schema or product services. Contention is
// reported as busy (UPDATE_BUSY), never waited on forever.
package nodelock

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/google/uuid"
)

// DefaultPath is the default lock file (§4 node paths).
const DefaultPath = "/var/lib/vpn-node/update.lock"

// ErrBusy means another process holds the lock (UPDATE_BUSY, §13.11).
var ErrBusy = errors.New("UPDATE_BUSY: node update lock is held by another process")

// Lock is a held exclusive flock. The descriptor stays open until Release.
type Lock struct {
	f *os.File
}

// holder is the metadata written only after flock succeeds (D-034d).
// StartTime is field 22 of /proc/<pid>/stat, in clock ticks since boot.
type holder struct {
	PID       int    `json:"pid"`
	BootID    string `json:"boot_id"`
	StartTime int64  `json:"start_time"`
}

// TryAcquire takes LOCK_EX|LOCK_NB before it writes holder metadata. It
// returns ErrBusy when the lock is held elsewhere and does not remove the
// file. A crashed holder is released by the kernel when its descriptor
// closes. Stale detection compares the recorded boot id, pid and process
// start time. A stale record does not justify deleting a file another
// process still has locked: the error names the reason and the flock stays.
func TryAcquire(path string) (*Lock, error) {
	return tryAcquire(path, "", "/proc/sys/kernel/random/boot_id")
}

func tryAcquire(path, fallback, bootPath string) (*Lock, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		if errors.Is(err, syscall.EWOULDBLOCK) {
			h, ok := readHolder(f)
			_ = f.Close()
			if ok {
				if reason, stale := holderStaleReason(h, bootID(bootPath, fallback)); stale {
					// The record is stale, but flock is still held. Do not unlink.
					return nil, fmt.Errorf("%w: %s", ErrBusy, reason)
				}
			}
			return nil, ErrBusy
		}
		_ = f.Close()
		return nil, fmt.Errorf("flock: %w", err)
	}
	if err := writeHolder(f, bootID(bootPath, fallback)); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	return &Lock{f: f}, nil
}

func readBootID() string {
	return bootID("/proc/sys/kernel/random/boot_id", "")
}

func bootID(path, fallback string) string {
	b, err := os.ReadFile(path)
	if err != nil {
		return fallback
	}
	id, err := uuid.Parse(strings.TrimSpace(string(b)))
	if err != nil || id == uuid.Nil {
		return fallback
	}
	return id.String()
}

func readHolder(f *os.File) (holder, bool) {
	st, err := f.Stat()
	if err != nil || st.Size() == 0 || st.Size() > 1<<20 {
		return holder{}, false
	}
	buf := make([]byte, st.Size())
	n, err := f.ReadAt(buf, 0)
	if err != nil || n == 0 {
		return holder{}, false
	}
	var h holder
	if json.Unmarshal(buf[:n], &h) != nil {
		return holder{}, false
	}
	return h, true
}

func writeHolder(f *os.File, boot string) error {
	start, ok := processStartTime(os.Getpid())
	if !ok {
		return errors.New("nodelock: process start time")
	}
	raw, err := json.Marshal(holder{PID: os.Getpid(), BootID: boot, StartTime: start})
	if err != nil {
		return err
	}
	if err := f.Truncate(0); err != nil {
		return err
	}
	if _, err := f.WriteAt(raw, 0); err != nil {
		return err
	}
	return f.Sync()
}

// holderStale reports whether a recorded holder cannot still be this boot's
// live process. A different boot id is stale even when the pid number has
// been reused. A dead pid is stale on the same boot. The same pid is stale
// when its /proc start time differs, which is how a reused pid is told apart
// from the process that took the lock.
func holderStale(h holder, boot string) bool {
	_, stale := holderStaleReason(h, boot)
	return stale
}

// holderStaleReason names why a record is stale: "boot id", "pid",
// "process" or "start time". A live flock holder is not stale.
func holderStaleReason(h holder, boot string) (string, bool) {
	if h.BootID != boot {
		return "boot id", true
	}
	if h.PID <= 0 {
		return "pid", true
	}
	if syscall.Kill(h.PID, 0) != nil {
		return "process", true
	}
	start, ok := processStartTime(h.PID)
	if !ok {
		return "process", true
	}
	if h.StartTime == 0 || h.StartTime != start {
		return "start time", true
	}
	return "", false
}

// processStartTime reads field 22 of /proc/<pid>/stat (starttime, clock ticks
// since boot). The command name is in parentheses and may itself contain
// spaces and parentheses, so the fields are counted after the last ')'.
func processStartTime(pid int) (int64, bool) {
	b, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return 0, false
	}
	return parseStatStart(string(b))
}

func parseStatStart(s string) (int64, bool) {
	i := strings.LastIndex(s, ")")
	if i < 0 || i+2 >= len(s) {
		return 0, false
	}
	fields := strings.Fields(s[i+2:])
	// Field 22 is index 19 of the fields that follow the command name.
	if len(fields) <= 19 {
		return 0, false
	}
	n, err := strconv.ParseInt(fields[19], 10, 64)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

// Acquire retries TryAcquire with a fixed interval until attempts run out or
// ctx ends (bounded wait, §13.11 UPDATE_BUSY).
func Acquire(ctx context.Context, path string, attempts int, interval time.Duration) (*Lock, error) {
	return AcquireWithBootID(ctx, path, attempts, interval, "")
}

// AcquireWithBootID uses fallback only if the kernel boot id is unreadable.
// It otherwise has the same bounded contention behavior as Acquire.
func AcquireWithBootID(ctx context.Context, path string, attempts int, interval time.Duration, fallback string) (*Lock, error) {
	if attempts < 1 {
		attempts = 1
	}
	var last error
	for i := 0; i < attempts; i++ {
		l, err := tryAcquire(path, fallback, "/proc/sys/kernel/random/boot_id")
		if err == nil {
			return l, nil
		}
		last = err
		if !errors.Is(err, ErrBusy) {
			return nil, err
		}
		if i == attempts-1 {
			break
		}
		t := time.NewTimer(interval)
		select {
		case <-ctx.Done():
			t.Stop()
			return nil, ctx.Err()
		case <-t.C:
		}
	}
	return nil, last
}

// Release drops the lock. It is safe to call more than once.
func (l *Lock) Release() error {
	if l == nil || l.f == nil {
		return nil
	}
	err := syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
	cerr := l.f.Close()
	l.f = nil
	if err != nil {
		return err
	}
	return cerr
}
